+// Regla de auditoría EMBA: todo motivo tiene al menos 10 caracteres después del trim.
+export const MOTIVO_MIN_CARACTERES = 10;
+
+// RF-005, ADR-002: anula una factura emitida. Devuelve una factura nueva; la original no cambia.
+export function anularFactura(factura, motivo) {
+  if (factura?.estado !== "emitida") throw new Error("Solo se anula una factura emitida");
+  const motivoLimpio = typeof motivo === "string" ? motivo.trim() : "";
+  if (motivoLimpio.length < MOTIVO_MIN_CARACTERES)
+    throw new Error(`El motivo es obligatorio y debe tener al menos ${MOTIVO_MIN_CARACTERES} caracteres`);
+  return Object.freeze({ ...factura, estado: "anulada", motivo: motivoLimpio });
+}
